	GATE_W[n] = w
	GATE_X[n] = x
	GATE_Y[n] = y
	GATE_DEST[n] = dest
	GATE_N = n + 1
end

local function gate_in(w, dest)
	for i = 0, GATE_N - 1 do
		if GATE_W[i] == w and GATE_DEST[i] == dest then return i end
	end
	return -1
end

local function add_town(w, x0, y0, x1, y1, name)
	local n = TOWN_N
	TOWN_W[n] = w
	TOWN_X0[n] = x0
	TOWN_Y0[n] = y0
	TOWN_X1[n] = x1
	TOWN_Y1[n] = y1
