	TOWN_N = n + 1
end

local function town_at(w, x, y)
	for i = 0, TOWN_N - 1 do
		if TOWN_W[i] == w and x >= TOWN_X0[i] and x <= TOWN_X1[i] and y >= TOWN_Y0[i] and y <= TOWN_Y1[i] then return i end
	end
	return -1
end

